def find_runs(arr, target):
    runs = []  # Each run is [start, end) where end is non-inclusive
    current = None
    current_end = -1
    for i, val in enumerate(arr):
        if val == target:
            if current is None:
                current = i
            current_end = i
        else:
            if current is not None:
                runs.append((current, current_end + 1))
                current = None
    if current is not None:
        runs.append((current, current_end + 1))
    return runs

